/// produces the same hash, regardless of which [`AtomStore`] (if any) is
/// involved. This is what allows [`Atom::get_hash`] to be consistent across
/// stores.
fn compute_hash(text: &str) -> u64 {
    let mut hasher = DefaultHasher::new();
    text.hash(&mut hasher);
    hasher.finish()
}

/// The reference-counted heap allocation backing an [`Atom`].
///
/// Both the originating [`AtomStore`] and every live [`Atom`] pointing at an
/// entry hold a strong reference; the entry is freed only once the last of
/// them goes away.
