        if ptr.as_ref().ref_count.fetch_sub(1, Ordering::Release) == 1 {
            // Synchronize with the `Release` decrements of every other owner
            // before running the destructor.
            fence(Ordering::Acquire);
            drop(Box::from_raw(ptr.as_ptr()));
        }
    }
