[metadata] {"type": "create", "filePath": "/workspace/repo/crates/hstr/src/tests.rs", "content": "use crate::{Atom, AtomStore};

#[test]
fn same_store_same_string_shares_data() {
    let mut store = AtomStore::default();

    let a = store.atom("hello");
    let b = store.atom("hello");

    // Interning the same string on one store shares the backing allocation.
    assert_eq!(a.unsafe_data, b.unsafe_data);
    assert_eq!(a, b);
}

#[test]
fn same_store_different_strings_differ() {
    let mut store = AtomStore::default();

    let a = store.atom("hello");
    let b = store.atom("world");

    assert_ne!(a.unsafe_data, b.unsafe_data);
    assert_ne!(a, b);
}

#[test]
fn different_stores_same_string_differ_in_data_but_compare_equal() {
    let mut store1 = AtomStore::default();
    let mut store2 = AtomStore::default();

    let a = store1.atom("hello");
    let b = store2.atom("hello");

    // Different stores never share an allocation ...
    assert_ne!(a.unsafe_data, b.unsafe_data);
    // ... but atoms for the same string still compare equal.
    assert_eq!(a, b);
}

#[test]
fn hash_is_consistent_across_stores() {
    let mut store1 = AtomStore::default();
    let mut store2 = AtomStore::default();

    let a = store1.atom("hello");
    let b = store2.atom("hello");

    assert_eq!(a.get_hash(), b.get_hash());
}

#[test]
fn atom_outlives_its_store() {
    let atom = {
        let mut store = AtomStore::default();
        store.atom("persistent")
    };

    // The store has been dropped, yet the atom is still usable.
    let cloned = atom.clone();
    assert_eq!(atom, cloned);
    assert_eq!(atom.as_str(), "persistent");
}

#[test]
fn accepts_owned_and_borrowed_strings() {
    let mut store = AtomStore::default();

    let from_str = store.atom("shared");
    let from_string = store.atom(String::from("shared"));

    assert_eq!(from_str.unsafe_data, from_string.unsafe_data);
    assert_eq!(from_str, from_string);
}
